// 1. Recupera os dados dos clientes do Webhook
const webhookItems = $("Clientes POST").all();

const clientes = webhookItems.flatMap(item => {
  const dados = item.json.body ?? item.json;

  return Array.isArray(dados) ? dados : [dados];
}).filter(cliente => cliente.nome && cliente.perfil);

// 2. Recupera o CSV retornado pelo HTTP Request
const httpItems = $("Perfil de Investimentos").all();

const resposta = httpItems[0]?.json;

if (!resposta) {
  throw new Error("Nenhum dado recebido do node HTTP Request.");
}

// O HTTP Request pode retornar o CSV em data, body
// ou diretamente como texto, dependendo da configuração.
let csv = typeof resposta === "string"
  ? resposta
  : resposta.data ?? resposta.body ?? resposta;

let investimentos;

// Caso o HTTP Request já retorne objetos estruturados
if (Array.isArray(csv)) {
  investimentos = csv;
} else if (typeof csv === "string") {
  // 3. Converte CSV em objetos JavaScript
  function separarCSV(linha) {
    return linha.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)
      ?.filter((campo, indice, arr) => indice < arr.length)
      .map(campo => {
        campo = campo.replace(/,$/, "");

        if (campo.startsWith('"') && campo.endsWith('"')) {
          campo = campo.slice(1, -1).replace(/""/g, '"');
        }

        return campo.trim();
      }) ?? [];
  }

  const linhas = csv.trim().split(/\r?\n/);

  const cabecalhos = separarCSV(linhas.shift())
    .map(campo => campo.replace(/^﻿/, ""));

  investimentos = linhas
    .filter(linha => linha.trim() !== "")
    .map(linha => {
      const valores = separarCSV(linha);

      return Object.fromEntries(
        cabecalhos.map((cabecalho, indice) => [
          cabecalho,
          valores[indice] ?? ""
        ])
      );
    });
} else {
  throw new Error(
    "O retorno do HTTP Request não contém um CSV ou uma lista de investimentos válida."
  );
}

// 4. Converte o saldo brasileiro para número
function converterSaldo(saldo) {
  if (typeof saldo === "number") return saldo;

  const valor = String(saldo ?? "")
    .replace(/R\$\s?/g, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();

  const numero = Number(valor);

  if (!Number.isFinite(numero)) {
    throw new Error(`Saldo inválido: ${saldo}`);
  }

  return numero;
}

// 5. Cruza perfil do cliente, saldo e investimento mínimo
return clientes.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const investimentosCompativeis = investimentos
    .filter(investimento => {
      const perfilCompativel =
        String(investimento.perfil).trim().toLowerCase() ===
        String(cliente.perfil).trim().toLowerCase();

      const minimo = Number(investimento.minimo);

      return (
        perfilCompativel &&
        Number.isFinite(minimo) &&
        saldo >= minimo
      );
    })
    .map(investimento => ({
      produto: investimento.produto,
      minimo: Number(investimento.minimo),
      rentabilidade: investimento.rentabilidade
    }));

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldoNumerico: saldo,
      perfil: cliente.perfil,
      investimentosCompativeis
    }
  };
});

const clientes = $input.all();

return clientes.map(item => {
  const {
    nome,
    email,
    perfil,
    investimentosCompativeis
  } = item.json;

  const investimentos = Array.isArray(investimentosCompativeis)
    ? investimentosCompativeis
    : [];

  // Monta a lista de investimentos compatíveis
  const listaInvestimentos = investimentos.length > 0
    ? investimentos.map(inv => {
        const minimo = Number(inv.minimo).toLocaleString("pt-BR", {
          style: "currency",
          currency: "BRL"
        });

        return `• ${inv.produto} — investimento inicial: ${minimo} — rentabilidade informada: ${inv.rentabilidade}`;
      }).join("\n")
    : "No momento, não encontramos opções que atendam aos critérios de perfil e saldo disponíveis.";

  // Assunto do e-mail
  const assunto = `Sugestões de investimento para você, ${nome}`;

  // Corpo personalizado do e-mail
  const mensagem = `Olá, ${nome}! Tudo bem?

Preparamos algumas opções de investimento considerando seu perfil ${perfil} e o saldo disponível informado.

Confira as opções compatíveis com esses critérios:

${listaInvestimentos}

Nossa sugestão é que você avalie cada alternativa considerando seus objetivos financeiros, prazo de investimento, liquidez e tolerância a riscos. Rentabilidades informadas não garantem resultados futuros.

Se tiver dúvidas, estamos à disposição para ajudar!

Um abraço,
Equipe de Investimentos`;

  return {
    json: {
      nome,
      email,
      perfil,
      assunto,
      mensagem
    }
  };
});
